        var signatures=new HashSet<String>();for(long index=0;index<128;index++){long seed=index*0x9E3779B97F4A7C15L;var a=((Optional<?>)call(structure,"previewLayout",seed)).orElseThrow();var b=((Optional<?>)call(structure,"previewLayout",seed)).orElseThrow();String signature=LegacyPoolComparison.signature(a);require(signature.equals(LegacyPoolComparison.signature(b)),"Theme selection changed for an identical seed");signatures.add(signature);for(var module:(List<?>)a){var e=call(module,"entry");var template=(NativeTemplate)call(e,"template");var stair=template.blocks().stream().filter(c->c.state().getBlock() instanceof StairBlock).findFirst().orElseThrow();require(stair.state().getValue(StairBlock.FACING)==Direction.EAST,"Palette lost stair facing");require(((Map<?,?>)call(e,"markers")).size()==1,"Theme lost a spawn marker");require(template.blocks().stream().filter(c->c.state().is(Blocks.CHEST)).findFirst().orElseThrow().metadata().getStringOr("CustomName","").equals("House supplies"),"Theme lost decorative metadata");}}
