        require(SiteSearch.search(input,SiteInspector.placements(checked,Identifier.withDefaultNamespace("overworld"),ID),bounds,true,0).getStringOr("status","").equals("incomplete"),"Expired search claimed completeness");require(SiteSearch.search(input,SiteInspector.placements(checked,Identifier.withDefaultNamespace("overworld"),ID),bounds,false).getListOrEmpty("results").isEmpty(),"Disabled structures produced search results");
