        var registered=new net.minecraft.world.level.levelgen.WorldDimensions(server.registryAccess().lookupOrThrow(Registries.LEVEL_STEM)).dimensions();for(var dimension:registered.keySet()){if(!com.gwsheridan.worldsunwritten.dimension.DimensionCatalog.inspect(server.registryAccess(),dimension,registered.get(dimension)).modes().contains(com.gwsheridan.worldsunwritten.api.DimensionAdapter.TerrainMode.SINGLE_BLOCK))continue;var target=Identifier.parse("validation:prepared_"+dimension.identifier().toString().replace(':','_'));var path=stat("AssemblyExports","bundle",server,draft,target,dimension.identifier(),"1.6.0",18L,"Validation");System.out.println("WA16_BUNDLE themed "+dimension.identifier()+" "+target+" "+path);}
